def apply_transformation(grid):
    rows = len(grid)
    cols = len(grid[0])
    # Create copy, starting with 0 background (will preserve 5s)
    result = [[cell for cell in row] for row in grid]

    # Find all positions with 5
    positions_5 = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 5]

    # For each pair of 5s in the same row, fill between them
    def mark_between_row(row_idx, col_indices, output):
        for i in range(len(col_indices)):
            for j in range(i+1, len(col_indices)):
                c1, c2 = col_indices[i], col_indices[j]
                for c in range(c1 + 1, c2):
                    output[row_idx][c] = 3

    # For each pair of 5s in the same column, fill between them
    def mark_between_col(col_idx, row_indices, output):
        for i in range(len(row_indices)):
            for j in range(i+1, len(row_indices)):
                r1, r2 = row_indices[i], row_indices[j]
                for r in range(r1 + 1, r2):
                    output[r][col_idx] = 3

    for r in range(rows):
        cols_5 = [c for c in range(cols) if grid[r][c] == 5]
        mark_between_row(r, cols_5, result)

    for c in range(cols):
        rows_5 = [r for r in range(rows) if grid[r][c] == 5]
        mark_between_col(c, rows_5, result)

    # Note: The 5s themselves remain 5 (not converted to 3)
    return result

