# Fixed theory: preserve original 5s, then fill 3s in between

def apply_transformation_fixed(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]  # Start with copy, preserving 5s

    # Mark all positions that need to be 3 (will overwrite 0s, not 5s)
    positions_to_mark = set()

    # Find all positions with 5
    positions_5 = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 5]

    # For each pair of 5s in the same row, fill between them with 3
    for r in range(rows):
        cols_5 = sorted([c for c in range(cols) if grid[r][c] == 5])
        for i in range(len(cols_5)):
            for j in range(i+1, len(cols_5)):
                c1, c2 = cols_5[i], cols_5[j]
                for c in range(c1 + 1, c2):
                    positions_to_mark.add((r, c))

    # For each pair of 5s in the same column, fill between them with 3
    for c in range(cols):
        rows_5 = sorted([r for r in range(rows) if grid[r][c] == 5])
        for i in range(len(rows_5)):
            for j in range(i+1, len(rows_5)):
                r1, r2 = rows_5[i], rows_5[j]
                for r in range(r1 + 1, r2):
                    positions_to_mark.add((r, c))

    # Now apply the 3s (only to positions that were 0, not 5s)
    for r, c in positions_to_mark:
        if output[r][c] == 0:  # Only change 0s, not 5s
            output[r][c] = 3

    return output

